package com.campusiq.platform.client; import org.jsoup.Jsoup; import org.jsoup.nodes.Document; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Component; import org.springframework.web.client.RestClient; import java.util.regex.*;
@Component public class CodeChefClient {private final RestClient http; public CodeChefClient(RestClient.Builder b,@Value("${platform.codechef.base-url}")String u){http=b.baseUrl(u).defaultHeader("User-Agent","Mozilla/5.0 CampusIQ/1.0").build();} public Profile profile(String username){try{return parse(http.get().uri("/users/"+username).retrieve().body(String.class));}catch(PlatformClientException e){throw e;}catch(Exception e){throw new PlatformClientException("CodeChef is unavailable or returned an invalid response",e);}} Profile parse(String html){if(html==null||html.contains("Just a moment")||html.contains("Access Denied"))throw new PlatformClientException("CodeChef blocked the profile request");Document d=Jsoup.parse(html);String rating=d.selectFirst(".rating-number")==null?null:d.selectFirst(".rating-number").text();if(rating==null||!rating.matches("\\d+"))throw new PlatformClientException("CodeChef profile was not found or layout changed");String text=d.text();Matcher star=Pattern.compile("(\\d★)").matcher(text);return new Profile(Long.valueOf(rating),numberAfter(text,"Global Rank"),numberAfter(text,"Country Rank"),numberAfter(text,"Total Problems Solved"),star.find()?star.group(1):null);} private Long numberAfter(String text,String label){Matcher m=Pattern.compile(label+"[^0-9]*(\\d[\\d,]*)",Pattern.CASE_INSENSITIVE).matcher(text);return m.find()?Long.valueOf(m.group(1).replace(",","")):null;} public record Profile(Long rating,Long globalRank,Long countryRank,Long totalSolved,String stars){} }
